 using System.Security.Claims;
 using Microsoft.AspNetCore.Components.Authorization;
 using Microsoft.AspNetCore.Components;
 using Microsoft.AspNetCore.Components.Web;
 using Microsoft.AspNetCore.Components.Server;
 using sv_254a8585e2f8474ab21ce03117a84779.Client;

 namespace sv_254a8585e2f8474ab21ce03117a84779.Auth;

 /// <summary>
 /// Server-side AuthenticationStateProvider that returns a hardcoded user
 /// and persists the auth state so the WebAssembly runtime can pick it up.
 /// </summary>
 internal sealed class HardcodedAuthenticationStateProvider
     : ServerAuthenticationStateProvider, IDisposable
 {
     private readonly PersistentComponentState _persistentState;
     private readonly PersistingComponentStateSubscription _subscription;
     private Task<AuthenticationState>? _authStateTask;

     public HardcodedAuthenticationStateProvider(PersistentComponentState persistentState)
     {
         _persistentState = persistentState;
         AuthenticationStateChanged += OnAuthenticationStateChanged;
         _subscription = _persistentState.RegisterOnPersisting(OnPersistingAsync, Microsoft.AspNetCore.Components.Web.RenderMode.InteractiveWebAssembly);

         // Set the hardcoded authenticated user.
         var claims = new List<Claim>
         {
             new(ClaimTypes.Name, "bob@example.com"),
             new(ClaimTypes.Email, "bob@example.com"),
             new(ClaimTypes.Role, "User"),
             new(ClaimTypes.Role, "Editor"),
         };

         var identity = new ClaimsIdentity(claims, authenticationType: "Hardcoded");
         SetAuthenticationState(Task.FromResult(new AuthenticationState(new ClaimsPrincipal(identity))));
     }

     private void OnAuthenticationStateChanged(Task<AuthenticationState> task)
     {
         _authStateTask = task;
     }

     private async Task OnPersistingAsync()
     {
         var authState = await (_authStateTask ?? GetAuthenticationStateAsync());
         var principal = authState.User;

         if (principal.Identity?.IsAuthenticated == true)
         {
             var userInfo = new UserInfo
             {
                 Email = principal.FindFirst(ClaimTypes.Email)?.Value
                         ?? principal.FindFirst(ClaimTypes.Name)?.Value
                         ?? string.Empty,
                 Roles = principal.FindAll(ClaimTypes.Role).Select(c => c.Value).ToArray(),
             };

             _persistentState.PersistAsJson(nameof(UserInfo), userInfo);
         }
     }

     public void Dispose()
     {
         _subscription.Dispose();
         AuthenticationStateChanged -= OnAuthenticationStateChanged;
     }
 }

